#include <BqLayout.h>
#include <stdint.h>
#include "RCC.h"
#include "GPIO.h"
#include "TIM14.h"
#include "I2C.h"
#include "SysCfg.h"
#include "SPI.h"
#include "NVIC.h"
#include "OLED_Driver.h"
#include "BQ25690_Driver.h"
#include "PAC193x_Driver.h"
#include "MeasLayout.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

uint32 Ticks;

uint32 SysTime(void)
{
    return Ticks;
}

uint8 TimePassed(uint32 timestamp, uint32 limit)
{
    uint8 ret = 0;
    if((Ticks - timestamp) >= limit)
    {
        ret = 1;
    }
    return ret;
}

void Led(void)
{
    GPIO_Set(PortA_5, Toggle);
    Ticks++;
}

int main(void)
{
    const dtGPIOConfig OutPPCfg = {.DefState = 0, .Mode = Output, .PUPD = NoPull, .Speed = Medium, .Type = PushPull};
    dtGPIOConfig I2cCfg = {.DefState = 0, .Mode = Alt6, .PUPD = NoPull, .Speed = Medium, .Type = OpenDrain};
    dtGPIOConfig spipin = {.DefState = 0, .Mode = Alt0, .PUPD = NoPull, .Speed = Medium, .Type = PushPull};
    dtRccClockTreeCfg ClockCfg = {
        .SysClockCfg = SysClock_HSI,    .LsiClock = 0,      .RtcClockSel = 0,   .AhbPrescaler = 0,
        .ApbPrescaler = 0,              .HsiDiv = 0,        .HsikerDiv = 0,     .SysDiv = 0,
        .Usart1ClockSel = 0,            .I2C1ClockSel = 0,  .I2SClockSel = 0,   .FdCanClockSel = 0};
    dtI2cConfig i2c_cfg = {.AnalogFilter = 0, .TimingReg = 0x70302E39};
    dtSpiConf spi_cfg = {.CHPA = 0, .CPOL = 0, .ClockDiv = SpiDiv16, .CsFrameLength = 1, .DataSize = Size8Bit, .Instance = 0, .LsbOrMsb = 0, .ChipSelectPin = PortA_4};

    uint32 TickStamp = 0;

    RCC_ClockTreeInit(ClockCfg);
    RCC_ClockEnable(RCC_GPIOA, Enable);
    RCC_ClockEnable(RCC_TIM14, Enable);
    RCC_ClockEnable(RCC_I2C1, Enable);
    RCC_ClockEnable(RCC_SYSCFG, Enable);
    RCC_ClockEnable(RCC_SPI1, Enable);

    SYSCFG_Remap(SYSCFG_RMP_PA11, 1);
    SYSCFG_Remap(SYSCFG_RMP_PA12, 1);

    GPIO_PinInit(PortA_7, OutPPCfg);
    GPIO_Set(PortA_7, Set);

    GPIO_PinInit(PortA_5, OutPPCfg);
    GPIO_PinInit(PortA_9, I2cCfg);
    GPIO_PinInit(PortA_10, I2cCfg);

    GPIO_PinInit(PortA_0, OutPPCfg); //CS
    GPIO_PinInit(PortA_3, OutPPCfg); //CS
    GPIO_PinInit(PortA_4, OutPPCfg); //CS
    GPIO_PinInit(PortA_1, spipin); //SCK
    GPIO_PinInit(PortA_2, spipin); //MOSI

    TIM14_Init(999, 47, Led);

    I2C_Init(I2C1, i2c_cfg);
    SPI_Init(spi_cfg);
    NVIC_EnableIRQ(IRQ_SPI1);

    OLED_Driver_Set(OledMode_On);
    uint8 layout = 0;

    /* Loop forever */
	for(;;)
	{
	    switch(layout)
	    {
	        case 0:
	            BqLayout_Status_Runnable();
	            break;
	        case 1:
	            BqLayout_Faults_Runnable();
	            break;
	        case 2:
	            MeasLayout_Layout();
	            break;
	    }

	    OLED_Driver_Runnable();
	    BQ25690_Runnable();
	    PAC_193x_Driver_Runnable();
	    if((Ticks - TickStamp) > 2000)
        {
	        if(layout == 3) layout = 0;
	        else layout++;
            TickStamp = Ticks;
        }
	}
}
